const r = await gm.query_log({ after: 14, js: "events.filter(e => e.kind === 'code-call' && e.body === 15 && (e.tool === 'grep' || e.tool === 'read_file' || e.tool === 'run_shell' || e.tool === 'list_dir')).map(e => ({seq:e.seq,tool:e.tool,args:e.args,output:e.output ? String(e.output).slice(0,5000) : '',error:e.error ? String(e.error).slice(0,500) : ''}))" });
let events = [];
try { events = JSON.parse(r.output); } catch { events = []; }
const greps = events.filter(e => e.tool === 'grep');
const readme = events.find(e => e.tool === 'read_file' && String(e.args?.path).includes('README'));
const gapsList = events.find(e => e.tool === 'list_dir');
const status = events.find(e => e.tool === 'run_shell' && String(e.args?.command).includes('git status'));
const head = events.find(e => e.tool === 'run_shell' && String(e.args?.command).includes('git rev-parse HEAD'));
const remote = events.find(e => e.tool === 'run_shell' && String(e.args?.command).includes('rev-parse origin/main'));
const ci = events.find(e => e.tool === 'run_shell' && String(e.args?.command).includes('gh run list'));
return { greps, readme, gapsList, status, head, remote, ci, total: events.length };

const hexPath = Array.from('gaps/netcode-optimization-gaps.md').map(c => c.charCodeAt(0).toString(16).padStart(2, '0')).join('') + '.html';
const [readme, gapDoc, siteHead, gapList, readmeGapRefs, gapSection, siteGapLink, siteGapPath, siteFileLinks, siteIndexSummary] = await Promise.all([
  gm.read_file({ path: 'README.md', limit: 100 }),
  gm.read_file({ path: 'gaps/netcode-optimization-gaps.md', limit: 260 }),
  gm.read_file({ path: 'site/index.html', limit: 40 }),
  gm.list_dir({ path: 'gaps' }),
  gm.grep({ pattern: 'gaps/|gap survey|netcode-optimization-gaps|morluto-rea-pr', root: 'README.md', mode: 'regex', scope: 'all', ignoreCase: true, limit: 50 }),
  gm.grep({ pattern: '## 6. Open items for the owner|^[1-5]\\. ', root: 'gaps/netcode-optimization-gaps.md', mode: 'regex', scope: 'all', limit: 20 }),
  gm.grep({ pattern: hexPath, root: 'site/index.html', mode: 'literal', scope: 'all', limit: 10 }),
  gm.grep({ pattern: 'gaps/netcode-optimization-gaps.md', root: 'site/index.html', mode: 'literal', scope: 'all', limit: 10 }),
  gm.grep({ pattern: 'href="files/', root: 'site/index.html', mode: 'literal', scope: 'all', limit: 1000 }),
  gm.grep({ pattern: 'files|index|files:|committed', root: 'site/index.html', mode: 'regex', scope: 'all', ignoreCase: true, limit: 20 }),
]);
const numbered = (text, filter) => text.split('\n').map((line, i) => ({ n: i + 1, line })).filter(filter);
const readmeLines = numbered(readme.output || '', () => true);
const gapLines = numbered(gapDoc.output || '', ({ line }) => /^## 6\. Open items for the owner$|^[1-5]\. /.test(line));
const siteHeadLines = numbered(siteHead.output || '', ({ line }) => /<h1|<h2|files|index|committed/i.test(line));
const fileLinkLines = (siteFileLinks.output || '').split('\n').filter(line => line.includes('href="files/') || line.includes('matches;'));
return {
  hexPath,
  readmeLines,
  gapLines,
  siteHeadLines,
  gapList,
  readmeGapRefs,
  gapSection,
  siteGapLink,
  siteGapPath,
  siteFileLinkCount: fileLinkLines.filter(line => line.includes('href="files/')).length,
  siteFileLinkSample: fileLinkLines.slice(0, 4),
  siteFileLinkTail: fileLinkLines.slice(-3),
  siteIndexSummary,
};
